      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na logística a montante offshore, plataformas são abastecidas regularmente por embarcações de apoio que partem de portos especializados denominados bases de apoio.",
          "trechos": [
            "Ecc8792f9c6c14268:0:694"
          ],
          "condicoes": [
            "Aplicável ao abastecimento de instalações offshore com suprimentos necessários."
          ],
          "limites": [
            "A fonte descreve o fluxo de suprimento de ida e não detalha o retorno a terra de resíduos, reparáveis ou embalagens.",
