            "Ecc8792f9c6c14268:1392:2082"
          ],
          "condicoes": [
            "Aplicável ao planejamento de recursos na cadeia de suprimento offshore, com embarcações para cargas e aeronaves para pessoas."
          ],
          "limites": [
            "A proposição é geral e não especifica critérios próprios para seleção de meios no retorno de resíduos ou materiais reparáveis.",
            "Não há conteúdo explícito sobre segregação, identificação, manifesto ou certificados de contêineres."
          ]
        }
      ]
